                <?php foreach (['device' => 'Geräte', 'regie' => 'Regie', 'other' => 'Sonstige'] as $value => $label): ?><option value="<?= $value ?>"<?= $selectedKind === $value ? ' selected' : '' ?>><?= $label ?></option><?php endforeach; ?>
