              <?php if ($storedKind === 'unclassified' && $selectedKind !== ''): ?><span class="small text-body-secondary"><i class="fa-solid fa-wand-magic-sparkles me-1" aria-hidden="true"></i>Vorschlag – bitte prüfen</span><?php endif; ?>
